import { uniqueStrings } from './unique_changed.mjs';

// Basic dedup preserving first occurrence and original spelling
const a = ['Apple', 'banana', 'APPLE', 'Banana', 'cherry', 'apple'];
const r1 = uniqueStrings(a);
console.log('r1:', JSON.stringify(r1));
console.assert(JSON.stringify(r1) === JSON.stringify(['Apple', 'banana', 'cherry']), 'r1 failed');

// Input not mutated
console.assert(JSON.stringify(a) === JSON.stringify(['Apple', 'banana', 'APPLE', 'Banana', 'cherry', 'apple']), 'input mutated');

// Whitespace not trimmed
const r2 = uniqueStrings(['  hi', 'HI', ' hi ', '  hi']);
console.log('r2:', JSON.stringify(r2));
console.assert(JSON.stringify(r2) === JSON.stringify(['  hi', ' hi ']), 'r2 failed');

// Empty array
console.assert(JSON.stringify(uniqueStrings([])) === '[]', 'empty failed');

// Single element
console.assert(JSON.stringify(uniqueStrings(['x'])) === '[\"x\"]', 'single failed');

// Non-ASCII unaffected (toLowerCase still applied)
const r3 = uniqueStrings(['É', 'é']);
console.log('r3:', JSON.stringify(r3));
console.assert(JSON.stringify(r3) === JSON.stringify(['É']), 'r3 failed');

console.log('All checks passed.');
"

